const YEARS = [...new Set(RAW.map(r => r.orderDate.split("/")[2]))].sort();
const MIN_YEAR = YEARS[0];
const MAX_YEAR = YEARS[YEARS.length - 1];

function Chip({ active, onClick, children, tone = "amber" }) {
  return (
    <button onClick={onClick} className={"chip" + (active ? " chip-active chip-" + tone : "")}>
      {children}
    </button>
  );
}

export default function App() {
  const [regions, setRegions] = useState(new Set());
  const [items, setItems] = useState(new Set());
  const [channel, setChannel] = useState("All");
  const [priorities, setPriorities] = useState(new Set());
  const [yearMin, setYearMin] = useState(MIN_YEAR);
  const [yearMax, setYearMax] = useState(MAX_YEAR);
  const [sortKey, setSortKey] = useState("revenue");

  function toggle(setFn, set, val) {
    const next = new Set(set);
    if (next.has(val)) next.delete(val); else next.add(val);
    setFn(next);
  }

  const filtered = useMemo(() => {
    return RAW.filter(r => {
      if (regions.size && !regions.has(r.region)) return false;
      if (items.size && !items.has(r.item)) return false;
      if (channel !== "All" && r.channel !== channel) return false;
      if (priorities.size && !priorities.has(r.priority)) return false;
      const y = r.orderDate.split("/")[2];
      if (y < yearMin || y > yearMax) return false;
      return true;
    });
  }, [regions, items, channel, priorities, yearMin, yearMax]);

  const kpis = useMemo(() => {
    const revenue = filtered.reduce((a, r) => a + r.revenue, 0);
    const profit = filtered.reduce((a, r) => a + r.profit, 0);
    const units = filtered.reduce((a, r) => a + r.units, 0);
    const margin = revenue ? (profit / revenue) * 100 : 0;
    return { revenue, profit, units, margin, count: filtered.length };
  }, [filtered]);

  const byYear = useMemo(() => {
    const map = {};
    filtered.forEach(r => {
      const y = r.orderDate.split("/")[2];
      if (!map[y]) map[y] = { year: y, revenue: 0, profit: 0 };
      map[y].revenue += r.revenue;
      map[y].profit += r.profit;
    });
    return Object.values(map).sort((a, b) => a.year.localeCompare(b.year));
  }, [filtered]);

  const byItem = useMemo(() => {
    const map = {};
    filtered.forEach(r => {
      if (!map[r.item]) map[r.item] = { item: r.item, revenue: 0, profit: 0, units: 0 };
      map[r.item].revenue += r.revenue;
      map[r.item].profit += r.profit;
      map[r.item].units += r.units;
    });
    return Object.values(map).sort((a, b) => b[sortKey] - a[sortKey]);
  }, [filtered, sortKey]);

  const byRegion = useMemo(() => {
    const map = {};
    filtered.forEach(r => {
      if (!map[r.region]) map[r.region] = { region: r.region, revenue: 0, profit: 0 };
      map[r.region].revenue += r.revenue;
      map[r.region].profit += r.profit;
    });
    return Object.values(map).sort((a, b) => b.revenue - a.revenue);
  }, [filtered]);

  const byChannel = useMemo(() => {
    const map = { Online: 0, Offline: 0 };
    filtered.forEach(r => { map[r.channel] += r.revenue; });
    return [
      { name: "Online", value: map.Online },
      { name: "Offline", value: map.Offline },
    ];
  }, [filtered]);

  const byPriority = useMemo(() => {
    const map = {};
    PRIORITY_ORDER.forEach(p => map[p] = 0);
    filtered.forEach(r => { map[r.priority] += r.revenue; });
    return PRIORITY_ORDER.map(p => ({ priority: PRIORITY_LABEL[p], value: map[p], key: p }));
  }, [filtered]);

  const topOrders = useMemo(() => {
    return [...filtered].sort((a, b) => b.revenue - a.revenue).slice(0, 10);
  }, [filtered]);

  const anyFilterActive = regions.size || items.size || channel !== "All" || priorities.size || yearMin !== MIN_YEAR || yearMax !== MAX_YEAR;

  return (
    <div className="wrap">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600&display=swap');

        * { box-sizing: border-box; }
        .wrap {
          background: #0A1A28;
          color: #E9EEF2;
          font-family: 'Inter', sans-serif;
          padding: 28px 24px 40px;
          min-height: 100vh;
          background-image:
            linear-gradient(#12293C 1px, transparent 1px),
            linear-gradient(90deg, #12293C 1px, transparent 1px);
          background-size: 48px 48px;
          background-position: -1px -1px;
        }
        .header {
          display: flex; justify-content: space-between; align-items: flex-end;
          flex-wrap: wrap; gap: 16px;
          border-bottom: 1px solid #23445C;
          padding-bottom: 18px; margin-bottom: 22px;
        }
        .eyebrow {
          font-family: 'IBM Plex Mono', monospace;
          font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase;
          color: #E4A73B; margin: 0 0 6px;
        }
        .title {
          font-family: 'Fraunces', serif; font-weight: 600;
          font-size: 32px; margin: 0; color: #F4F1E8;
          letter-spacing: -0.01em;
        }
        .subtitle {
          font-family: 'IBM Plex Mono', monospace; font-size: 12px;
          color: #7FA0B5; margin-top: 6px;
        }
        .stamp {
          font-family: 'IBM Plex Mono', monospace;
          font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase;
          color: #4FB3A9; border: 1px solid #2E5C55; border-radius: 3px;
          padding: 6px 12px; transform: rotate(-2deg);
        }

        .kpi-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 24px; }
        .kpi-card {
          background: #0F2434; border: 1px solid #1E3E54; border-radius: 6px;
          padding: 16px 18px; position: relative;
        }
        .kpi-card::before {
          content: ''; position: absolute; top: 0; left: 0; width: 3px; height: 100%;
          background: var(--accent, #E4A73B); border-radius: 6px 0 0 6px;
        }
        .kpi-label {
          font-family: 'IBM Plex Mono', monospace; font-size: 10.5px;
          letter-spacing: 0.1em; text-transform: uppercase; color: #7FA0B5; margin: 0 0 8px;
        }
        .kpi-value {
          font-family: 'Fraunces', serif; font-weight: 600; font-size: 26px;
          color: #F4F1E8; margin: 0; font-variant-numeric: tabular-nums;
        }
        .kpi-sub { font-family: 'IBM Plex Mono', monospace; font-size: 11px; color: #5C7A8C; margin-top: 4px; }

        .panel {
          background: #0F2434; border: 1px solid #1E3E54; border-radius: 6px;
          padding: 18px 20px; margin-bottom: 18px;
        }
        .panel-title {
          font-family: 'IBM Plex Mono', monospace; font-size: 11px;
          letter-spacing: 0.1em; text-transform: uppercase; color: #E4A73B;
          margin: 0 0 14px; display: flex; align-items: center; justify-content: space-between;
        }

        .filter-group { margin-bottom: 12px; }
        .filter-group:last-child { margin-bottom: 0; }
        .filter-label {
          font-family: 'IBM Plex Mono', monospace; font-size: 10px; letter-spacing: 0.08em;
          text-transform: uppercase; color: #5C7A8C; margin-bottom: 7px; display: block;
        }
        .chip-row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
        .chip {
          font-family: 'Inter', sans-serif; font-size: 12.5px; color: #B7CBD8;
          background: #142E42; border: 1px solid #23445C; border-radius: 4px;
          padding: 5px 11px; cursor: pointer; transition: all 0.12s ease;
        }
        .chip:hover { border-color: #35617F; }
        .chip-active.chip-amber { background: #2E250F; border-color: #E4A73B; color: #F5C97A; }
        .chip-active.chip-teal { background: #12312D; border-color: #4FB3A9; color: #8FDBD1; }
        .chip-active.chip-coral { background: #33200F; border-color: #C9714A; color: #EBA47D; }
        .year-select {
          font-family: 'IBM Plex Mono', monospace; font-size: 12.5px; color: #E9EEF2;
          background: #142E42; border: 1px solid #23445C; border-radius: 4px;
          padding: 5px 8px;
        }
        .clear-btn {
          font-family: 'IBM Plex Mono', monospace; font-size: 10.5px; color: #C9714A;
          background: none; border: none; cursor: pointer; text-decoration: underline;
          letter-spacing: 0.05em;
        }

        .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
        .legend-row { display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 6px; }
        .legend-item { display: flex; align-items: center; gap: 6px; font-family: 'IBM Plex Mono', monospace; font-size: 11px; color: #9FB6C4; }
        .legend-swatch { width: 9px; height: 9px; border-radius: 2px; }

        table.manifest { width: 100%; border-collapse: collapse; font-family: 'IBM Plex Mono', monospace; font-size: 12px; }
        table.manifest th {
          text-align: left; color: #5C7A8C; font-weight: 500; font-size: 10.5px;
          letter-spacing: 0.06em; text-transform: uppercase; padding: 0 10px 8px; border-bottom: 1px solid #1E3E54;
        }
        table.manifest td { padding: 8px 10px; border-bottom: 1px solid #16293A; color: #C7D8E2; }
        table.manifest tr:last-child td { border-bottom: none; }
        table.manifest td.num { text-align: right; font-variant-numeric: tabular-nums; }
        table.manifest td.profit { color: #7FD8C6; }
        .tag {
          display: inline-block; font-size: 10px; padding: 2px 7px; border-radius: 3px;
          border: 1px solid #23445C; color: #9FB6C4; letter-spacing: 0.03em;
        }

        .active-summary {
          font-family: 'IBM Plex Mono', monospace; font-size: 11.5px; color: #7FA0B5;
          margin-top: 10px; padding-top: 10px; border-top: 1px dashed #23445C;
        }

        @media (max-width: 860px) {
          .kpi-row { grid-template-columns: repeat(2, 1fr); }
          .grid-2 { grid-template-columns: 1fr; }
        }
      `}</style>

      <div className="header">
        <div>
          <p className="eyebrow">Manifest No. 0001&ndash;{String(RAW.length).padStart(4,"0")} &middot; {MIN_YEAR}&ndash;{MAX_YEAR}</p>
          <h1 className="title">Global Trade Ledger</h1>
          <p className="subtitle">{filtered.length.toLocaleString()} of {RAW.length.toLocaleString()} shipments in view &middot; {ALL_REGIONS.length} regions &middot; {ALL_ITEMS.length} commodity classes</p>
        </div>
        <div className="stamp">Cleared &middot; live filtered</div>
      </div>

      <div className="kpi-row">
        <div className="kpi-card" style={{ "--accent": "#E4A73B" }}>
          <p className="kpi-label">Total Revenue</p>
          <p className="kpi-value">{fmtCurrency(kpis.revenue)}</p>
          <p className="kpi-sub">{fmtFull(kpis.revenue)}</p>
        </div>
        <div className="kpi-card" style={{ "--accent": "#4FB3A9" }}>
          <p className="kpi-label">Total Profit</p>
          <p className="kpi-value">{fmtCurrency(kpis.profit)}</p>
          <p className="kpi-sub">Margin {kpis.margin.toFixed(1)}%</p>
        </div>
        <div className="kpi-card" style={{ "--accent": "#C9714A" }}>
          <p className="kpi-label">Units Sold</p>
          <p className="kpi-value">{fmtNum(kpis.units)}</p>
          <p className="kpi-sub">{kpis.units.toLocaleString()} units</p>
        </div>
        <div className="kpi-card" style={{ "--accent": "#7C9CB8" }}>
          <p className="kpi-label">Shipments</p>
          <p className="kpi-value">{kpis.count.toLocaleString()}</p>
          <p className="kpi-sub">avg {fmtCurrency(kpis.count ? kpis.revenue / kpis.count : 0)} / order</p>
        </div>
      </div>

      <div className="panel">
        <p className="panel-title">
          <span>Manifest Filters</span>
          {anyFilterActive && (
            <button className="clear-btn" onClick={() => {
              setRegions(new Set()); setItems(new Set()); setChannel("All");
              setPriorities(new Set()); setYearMin(MIN_YEAR); setYearMax(MAX_YEAR);
            }}>clear all</button>
          )}
        </p>

        <div className="filter-group">
          <span className="filter-label">Region</span>
          <div className="chip-row">
            {ALL_REGIONS.map(r => (
              <Chip key={r} tone="amber" active={regions.has(r)} onClick={() => toggle(setRegions, regions, r)}>
                {REGION_ABBR[r] || r}
              </Chip>
            ))}
          </div>
        </div>

        <div className="filter-group">
          <span className="filter-label">Commodity</span>
          <div className="chip-row">
            {ALL_ITEMS.map(it => (
              <Chip key={it} tone="teal" active={items.has(it)} onClick={() => toggle(setItems, items, it)}>
                {it}
              </Chip>
            ))}
          </div>
        </div>

        <div className="filter-group">
          <span className="filter-label">Channel &amp; Priority</span>
          <div className="chip-row">
            {["All", "Online", "Offline"].map(c => (
              <Chip key={c} tone="coral" active={channel === c} onClick={() => setChannel(c)}>{c}</Chip>
            ))}
            <span style={{ width: 1, height: 18, background: "#23445C", margin: "0 4px" }} />
            {PRIORITY_ORDER.map(p => (
              <Chip key={p} tone="coral" active={priorities.has(p)} onClick={() => toggle(setPriorities, priorities, p)}>
                {PRIORITY_LABEL[p]}
              </Chip>
            ))}
            <span style={{ width: 1, height: 18, background: "#23445C", margin: "0 4px" }} />
            <select className="year-select" value={yearMin} onChange={e => setYearMin(e.target.value)}>
              {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
            <span style={{ color: "#5C7A8C", fontSize: 12 }}>to</span>
            <select className="year-select" value={yearMax} onChange={e => setYearMax(e.target.value)}>
              {YEARS.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="panel">
        <p className="panel-title">Revenue &amp; Profit by Year</p>
        <div className="legend-row">
          <span className="legend-item"><span className="legend-swatch" style={{ background: "#E4A73B" }} />Revenue</span>
          <span className="legend-item"><span className="legend-swatch" style={{ background: "#4FB3A9" }} />Profit</span>
        </div>
        <ResponsiveContainer width="100%" height={260}>
          <ComposedChart data={byYear} margin={{ top: 4, right: 8, left: 0, bottom: 0 }}>
            <CartesianGrid stroke="#16293A" vertical={false} />
            <XAxis dataKey="year" tick={{ fill: "#7FA0B5", fontSize: 11, fontFamily: "IBM Plex Mono" }} axisLine={{ stroke: "#23445C" }} tickLine={false} />
            <YAxis tickFormatter={fmtCurrency} tick={{ fill: "#7FA0B5", fontSize: 11, fontFamily: "IBM Plex Mono" }} axisLine={false} tickLine={false} width={56} />
            <Tooltip
              contentStyle={{ background: "#0F2434", border: "1px solid #23445C", borderRadius: 6, fontFamily: "IBM Plex Mono", fontSize: 12 }}
              labelStyle={{ color: "#E4A73B" }}
              formatter={(v) => fmtFull(v)}
            />
            <Area type="monotone" dataKey="revenue" stroke="#E4A73B" fill="#E4A73B" fillOpacity={0.12} strokeWidth={2} />
            <Line type="monotone" dataKey="profit" stroke="#4FB3A9" strokeWidth={2} dot={{ r: 3, fill: "#4FB3A9" }} />
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      <div className="grid-2">
        <div className="panel">
          <p className="panel-title">
            <span>Revenue by Commodity</span>
            <span style={{ display: "flex", gap: 6 }}>
              <Chip tone="amber" active={sortKey === "revenue"} onClick={() => setSortKey("revenue")}>revenue</Chip>
              <Chip tone="teal" active={sortKey === "profit"} onClick={() => setSortKey("profit")}>profit</Chip>
            </span>
          </p>
          <ResponsiveContainer width="100%" height={320}>
            <BarChart data={byItem} layout="vertical" margin={{ top: 0, right: 20, left: 0, bottom: 0 }}>
              <CartesianGrid stroke="#16293A" horizontal={false} />
              <XAxis type="number" tickFormatter={fmtCurrency} tick={{ fill: "#7FA0B5", fontSize: 10.5, fontFamily: "IBM Plex Mono" }} axisLine={{ stroke: "#23445C" }} tickLine={false} />
              <YAxis type="category" dataKey="item" width={92} tick={{ fill: "#B7CBD8", fontSize: 11.5, fontFamily: "Inter" }} axisLine={false} tickLine={false} />
              <Tooltip
                contentStyle={{ background: "#0F2434", border: "1px solid #23445C", borderRadius: 6, fontFamily: "IBM Plex Mono", fontSize: 12 }}
                labelStyle={{ color: "#E4A73B" }}
                formatter={(v) => fmtFull(v)}
              />
              <Bar dataKey={sortKey} radius={[0, 3, 3, 0]}>
                {byItem.map((entry, i) => <Cell key={entry.item} fill={ITEM_COLORS[i % ITEM_COLORS.length]} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="panel">
          <p className="panel-title">Revenue by Region</p>
          <ResponsiveContainer width="100%" height={320}>
            <BarChart data={byRegion} layout="vertical" margin={{ top: 0, right: 20, left: 0, bottom: 0 }}>
              <CartesianGrid stroke="#16293A" horizontal={false} />
              <XAxis type="number" tickFormatter={fmtCurrency} tick={{ fill: "#7FA0B5", fontSize: 10.5, fontFamily: "IBM Plex Mono" }} axisLine={{ stroke: "#23445C" }} tickLine={false} />
              <YAxis type="category" dataKey="region" width={130} tickFormatter={(r) => REGION_ABBR[r] || r} tick={{ fill: "#B7CBD8", fontSize: 11, fontFamily: "Inter" }} axisLine={false} tickLine={false} />
              <Tooltip
                contentStyle={{ background: "#0F2434", border: "1px solid #23445C", borderRadius: 6, fontFamily: "IBM Plex Mono", fontSize: 12 }}
                labelStyle={{ color: "#E4A73B" }}
                formatter={(v) => fmtFull(v)}
                labelFormatter={(r) => REGION_ABBR[r] || r}
              />
              <Bar dataKey="revenue" fill="#7C9CB8" radius={[0, 3, 3, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid-2">
        <div className="panel">
          <p className="panel-title">Channel Split</p>
          <ResponsiveContainer width="100%" height={220}>
            <PieChart>
              <Pie data={byChannel} dataKey="value" nameKey="name" innerRadius={55} outerRadius={85} paddingAngle={3}>
                <Cell fill="#E4A73B" />
                <Cell fill="#4FB3A9" />
              </Pie>
              <Tooltip
                contentStyle={{ background: "#0F2434", border: "1px solid #23445C", borderRadius: 6, fontFamily: "IBM Plex Mono", fontSize: 12 }}
                formatter={(v) => fmtFull(v)}
              />
              <Legend
                verticalAlign="bottom"
                formatter={(value) => <span style={{ color: "#B7CBD8", fontFamily: "IBM Plex Mono", fontSize: 11.5 }}>{value}</span>}
              />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="panel">
          <p className="panel-title">Revenue by Order Priority</p>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={byPriority} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <CartesianGrid stroke="#16293A" vertical={false} />
              <XAxis dataKey="priority" tick={{ fill: "#7FA0B5", fontSize: 11, fontFamily: "IBM Plex Mono" }} axisLine={{ stroke: "#23445C" }} tickLine={false} />
              <YAxis tickFormatter={fmtCurrency} tick={{ fill: "#7FA0B5", fontSize: 10.5, fontFamily: "IBM Plex Mono" }} axisLine={false} tickLine={false} width={54} />
              <Tooltip
                contentStyle={{ background: "#0F2434", border: "1px solid #23445C", borderRadius: 6, fontFamily: "IBM Plex Mono", fontSize: 12 }}
                formatter={(v) => fmtFull(v)}
              />
              <Bar dataKey="value" radius={[3, 3, 0, 0]}>
                {byPriority.map((entry) => (
                  <Cell key={entry.key} fill={entry.key === "C" ? "#C9714A" : entry.key === "H" ? "#E4A73B" : entry.key === "M" ? "#7C9CB8" : "#4FB3A9"} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="panel">
        <p className="panel-title">Top 10 Shipments by Revenue</p>
        <table className="manifest">
          <thead>
            <tr>
              <th>Order ID</th><th>Region</th><th>Commodity</th><th>Channel</th>
              <th className="num">Units</th><th className="num">Revenue</th><th className="num">Profit</th>
            </tr>
          </thead>
          <tbody>
            {topOrders.map(o => (
              <tr key={o.orderId}>
                <td>{o.orderId}</td>
                <td>{REGION_ABBR[o.region] || o.region}</td>
                <td>{o.item}</td>
                <td><span className="tag">{o.channel}</span></td>
                <td className="num">{o.units.toLocaleString()}</td>
                <td className="num">{fmtFull(o.revenue)}</td>
                <td className="num profit">{fmtFull(o.profit)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="active-summary">
        {filtered.length.toLocaleString()} shipments &middot; {fmtFull(kpis.revenue)} revenue &middot; window {yearMin}&ndash;{yearMax}
      </div>
    </div>
  );
}
